from research_helpers import *
a=ev('https://www.pahc.com/new-products/','Current acquired medicated feed and water-soluble portfolio. Brand offerings consolidated across animal species; no worldwide authorization inferred.')
b=ev('https://www.pahc.com/anticoccidial/home/','Six named anticoccidial brands and active ingredients; availability explicitly country-dependent.')
c=ev('https://www.pahc.com/mb1/home/','Current MB-1 live attenuated IBD vaccine identity and hatchery administration.')
d=ev('https://www.pahc.com/vaccines/ibvar206-map/','Current TAbic IBVAR206 vaccine and epidemiological applicability; map countries are not assumed marketing authorizations.')
e=ev('https://www.pahc.com/product_services/swine/','Current MJPRRS vaccine identity; product marketed and manufactured by Phibro.')
f=ev('https://www.pahc.com/dfm/microlife-poultry/','MicroLife Prime and Pace microbial feed products distinguished; not medicines.')
g=ev('https://www.pahc.com/dfm/microbase/','Bacillus plus protease/cellulase manure-treatment formulation; named product body reviewed, placeholder resource cards ignored.')
h=ev('https://www.pahc.com/autogenous_vaccine/home/','Tailor-Made autogenous vaccine offering and EASE antigen-production technology; customized batches not invented as individual SKUs.')
