products=[]
for n,desc in [('Terramycin water-soluble powder','Oxytetracycline hydrochloride veterinary antimicrobial formulation.'),('Avatec','Lasalocid medicated feed additive for poultry coccidiosis prevention.'),('BMD','Bacitracin methylenedisalicylate veterinary feed-additive and soluble-powder offering.'),('L-S 50 Water Soluble Powder','Lincomycin-spectinomycin poultry antimicrobial combination.'),('Lincomix','Lincomycin veterinary medicated feed-additive offering.'),('Robenz','Robenidine hydrochloride poultry anticoccidial feed additive.'),('Zoamix','Zoalene poultry anticoccidial feed additive.'),('Aureomix S 40/40 Granular','Chlortetracycline/sulfamethazine medicated feed combination for swine.'),('Triamulox Liquid Concentrate','Tiamulin hydrogen fumarate veterinary antimicrobial for drinking-water administration.')]:
 products.append(p(n,desc,a,life='commercial',roles=['commercial_partner'],typ='product'))
for n,ingredient in [('Nicarb','nicarbazin'),('Nicarmix','nicarbazin'),('Coxistac','salinomycin'),('Aviax','semduramicin'),('Aviax Plus','semduramicin and nicarbazin'),('Avensin','monensin')]:
 products.append(p(n,'Branded poultry anticoccidial formulation containing '+ingredient+'; availability varies by territory.',b,life='commercial',roles=['commercial_partner'],typ='product'))
products += [p('Phibro MB-1','Live attenuated infectious-bursal-disease poultry vaccine for hatchery administration.',c,life='commercial',typ='product'),p('TAbic IBVAR206','Poultry infectious-bronchitis vaccine addressing Variant 2 epidemiology.',d,life='commercial',typ='product'),p('MJPRRS','Veterinary PRRS vaccine offering for swine.',e,life='commercial',roles=['manufacturer'],typ='product'),p('MicroLife Prime','Four-species Bacillus microbial feed formulation for poultry.',f,life='commercial',typ='product',sub='industrial_biotechnology'),p('MicroLife Pace','Bacillus subtilis and B. licheniformis microbial feed formulation.',f,life='commercial',typ='product',sub='industrial_biotechnology'),p('MicroBase BioBuster Pit & Pond','Bacillus bacteria plus protease and cellulase enzymes for livestock manure decomposition.',g,life='commercial',typ='product',sub='industrial_biotechnology'),p('Phibro Tailor-Made autogenous vaccines','Customized veterinary bacterial and viral vaccine offering; individual farm-specific batches not enumerated.',h,life='commercial',roles=['manufacturer'],typ='product'),p('Phibro EASE','Enhanced Antigen Surface Expression bacterial-growth technology supporting autogenous vaccine production.',h,life='commercial',typ='technology',sub='research_tools'),p('TAbic','Effervescent-tablet technology for vaccine-antigen formulation and delivery; not an independent antigen or vaccine.',i,life='commercial',typ='technology',sub='research_tools')]
co=dict(company_id='cmp_32d19ad0-588e-4a28-97a4-136c571d95f0',products=products,evidence=[a,b,c,d,e,f,g,h,i],status='partial',coverage_note='24 branded veterinary formulations, microbial products, custom vaccine offering and technologies. Territory remains unknown where current catalogue does not establish precise availability; no global approval inferred. Brand products can share active ingredients and are not counted as unique molecules. Partial: full regional vaccine/medicated-feed catalogues, microbial grades, aquaculture and ethanol/bioprocess offerings, adjuvants and legacy products remain. Ordinary mineral feeds not automatically biotechnology; platforms overlap vaccine products.')
assert len(products)==24
(out/'batch-0402.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
